std::size_t i = *tabind;
std::size_t nbuckets = ckh->nbuckets;
auto *buckets = ckh->buckets;
while (true) {
    ++i;
    if (i >= nbuckets) {
        *tabind = nbuckets;
        return true; // iteration complete
    }
    if (buckets[i].key != nullptr) {
        *tabind = i;
        *key = buckets[i].key;
        *data = buckets[i].data;
        return false; // element found
    }
}

